//! WebGAL 项目快照打包命令行工具
//!
//! 用法: `webgal-snapshot [选项] <项目路径>...`
//!
//! 每个项目依次执行扫描与打包两步, 并以 Cargo 风格输出进度:
//! * 左侧为绿色标题, 中间为进度条, 右侧为详细描述.

use std::{
    collections::HashSet,
    io::{self, IsTerminal},
    path::{Path, PathBuf},
    process,
    sync::Mutex,
    time::{Duration, Instant},
};

use clap::{Parser, ValueEnum};
use console::style;
use indicatif::{MultiProgress, ProgressBar, ProgressStyle};
use webgal_snapshot::{Error, PackerBuilder, ProgressReporter};
use zip::CompressionMethod;

// -------- 命令行参数 --------

/// WebGAL 项目快照打包工具
///
/// 将开发中的 WebGAL 项目打包为精简压缩包: 游戏资源仅打包被引用的部分, 其余资源全部保留.
#[derive(Debug, Parser)]
#[command(name = "webgal-snapshot", version, about = "WebGAL 项目快照打包工具")]
struct Cli {
    /// 一个或多个 WebGAL 项目根目录 (包含 `game/` 子目录)
    #[arg(required = true)]
    projects: Vec<PathBuf>,

    /// 输出目录 (默认: 当前目录, 文件名: <项目名>-snapshot.zip)
    #[arg(short, long, default_value = ".")]
    output_dir: PathBuf,

    /// 压缩方式
    #[arg(short, long, value_enum, default_value_t = CompressionArg::Deflated)]
    compression: CompressionArg,

    /// 跟随符号链接遍历目录
    #[arg(short = 'f', long)]
    follow_symlinks: bool,
}

/// 压缩方式
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
enum CompressionArg {
    Stored,
    Deflated,
    Deflate64,
    Bzip2,
    Zstd,
    Lzma,
    Ppmd,
}

impl std::fmt::Display for CompressionArg {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(match self {
            CompressionArg::Stored => "stored",
            CompressionArg::Deflated => "deflated",
            CompressionArg::Deflate64 => "deflate64",
            CompressionArg::Bzip2 => "bzip2",
            CompressionArg::Zstd => "zstd",
            CompressionArg::Lzma => "lzma",
            CompressionArg::Ppmd => "ppmd",
        })
    }
}

impl From<CompressionArg> for CompressionMethod {
    fn from(value: CompressionArg) -> Self {
        match value {
            CompressionArg::Stored => CompressionMethod::Stored,
            CompressionArg::Deflated => CompressionMethod::Deflated,
            CompressionArg::Deflate64 => CompressionMethod::Deflate64,
            CompressionArg::Bzip2 => CompressionMethod::Bzip2,
            CompressionArg::Zstd => CompressionMethod::Zstd,
            CompressionArg::Lzma => CompressionMethod::Lzma,
            CompressionArg::Ppmd => CompressionMethod::Ppmd,
        }
    }
}

// -------- 进度展示 --------

/// 进度条宽度
const BAR_WIDTH: usize = 20;

/// 右侧待处理队列展示的文件数
const QUEUE_LEN: usize = 3;

/// 扫描行模板 (无进度条)
const SCAN_TEMPLATE: &str = "{prefix:.green.bold}  {msg}";

/// 打包行模板
const PACK_TEMPLATE: &str = "{prefix:.green.bold}  [{bar:20}] {pos}/{len} ({percent}%)  {msg}";

/// 进度汇报器 (基于 indicatif)
///
/// 终端中由 [`MultiProgress`] 管理两行进度: 扫描行 (无进度条) 与打包行 (进度条).
/// 非终端时 indicatif 不渲染, 由本汇报器在步骤完成时直接输出结果行.
struct Reporter {
    /// 项目名称
    project: String,
    /// 输出是否为终端
    tty: bool,
    /// 进度条管理器
    multi: MultiProgress,
    /// 扫描进度 (无进度条样式)
    scan_bar: Mutex<Option<ProgressBar>>,
    /// 打包进度
    pack_bar: Mutex<Option<ProgressBar>>,
    /// 非终端输出所需的状态
    plain: Mutex<PlainState>,
}

/// 进度汇报器的补充状态
#[derive(Default)]
struct PlainState {
    /// 待打包文件列表
    pack_files: Vec<String>,
    /// 待打包文件总体积
    pack_total_size: u64,
}

impl Reporter {
    fn new(project: String, tty: bool) -> Self {
        Self {
            project,
            tty,
            multi: MultiProgress::new(),
            scan_bar: Mutex::new(None),
            pack_bar: Mutex::new(None),
            plain: Mutex::new(PlainState::default()),
        }
    }

    /// 创建并注册一个进度条
    fn create_bar(&self, title: &str, template: &str) -> ProgressBar {
        let bar = self.multi.add(ProgressBar::new(1));
        let style = ProgressStyle::with_template(template)
            .expect("静态模板不应出错")
            .progress_chars("█░");
        bar.set_style(style);
        bar.set_prefix(title.to_string());
        bar
    }

    /// 打印错误
    ///
    /// 终端中通过 [`MultiProgress::println`] 输出在进度行上方; 非终端直接输出.
    fn print_error(&self, error: &Error) {
        let message = format!("error: {}", format_error(error));
        if self.tty {
            let _ = self
                .multi
                .println(style(message).for_stderr().red().to_string());
        } else {
            eprintln!("{message}");
        }
    }

    /// 扫描完成行 (非终端输出)
    fn scan_done_line(&self, count: usize, size: u64) -> String {
        format!(
            "扫描 {}  完成 {count} 个文件 · {}",
            self.project,
            format_size(size)
        )
    }

    /// 打包完成行 (非终端输出)
    fn pack_done_line(&self, total: usize, total_size: u64, final_size: u64) -> String {
        format!(
            "打包 {}  {} {total}/{total} (100%)  {}",
            self.project,
            progress_bar(1.0),
            pack_sizes(total_size, final_size)
        )
    }
}

impl ProgressReporter for Reporter {
    fn on_scan_start(&self) {
        if self.tty {
            let bar = self.create_bar(&format!("扫描 {}", self.project), SCAN_TEMPLATE);
            bar.set_message(format!("正在收集 · 0 个文件 · {}", format_size(0)));
            *self.scan_bar.lock().unwrap() = Some(bar);
        }
    }

    fn on_scan_file(&self, path: &Path, index: usize, cumulative_size: u64) {
        if let Some(bar) = self.scan_bar.lock().unwrap().as_ref() {
            bar.set_message(format!(
                "正在收集 {} · {} 个文件 · {}",
                file_name(path),
                index,
                format_size(cumulative_size)
            ));
        }
    }

    fn on_scan_error(&self, error: &Error) -> bool {
        self.print_error(error);
        false
    }

    fn on_scan_complete(&self, count: usize, total_size: u64) {
        let message = format!("完成 {count} 个文件 · {}", format_size(total_size));
        match (self.tty, self.scan_bar.lock().unwrap().take()) {
            (true, Some(bar)) => bar.finish_with_message(message),
            _ => eprintln!("{}", self.scan_done_line(count, total_size)),
        }
    }

    fn on_pack_start(&self, files: &[PathBuf], total_size: u64) {
        let names: Vec<String> = files.iter().map(|path| file_name(path)).collect();
        let total = names.len();
        {
            let mut plain = self.plain.lock().unwrap();
            plain.pack_files = names.clone();
            plain.pack_total_size = total_size;
        }

        if self.tty {
            let bar = self.create_bar(&format!("打包 {}", self.project), PACK_TEMPLATE);
            bar.set_length(total as u64);
            bar.set_message(pack_message(0, total, 0, 0, &names, false));
            *self.pack_bar.lock().unwrap() = Some(bar);
        }
    }

    fn on_pack_file(
        &self,
        _path: &Path,
        index: usize,
        cumulative_size: u64,
        cumulative_compressed_size: u64,
    ) {
        let plain = self.plain.lock().unwrap();
        let total = plain.pack_files.len();
        let message = pack_message(
            index,
            total,
            cumulative_size,
            cumulative_compressed_size,
            &plain.pack_files,
            false,
        );
        drop(plain);

        if let Some(bar) = self.pack_bar.lock().unwrap().as_ref() {
            bar.set_position(index as u64);
            bar.set_message(message);
        }
    }

    fn on_pack_error(&self, error: &Error) -> bool {
        self.print_error(error);
        false
    }

    fn on_pack_complete(&self, final_size: u64) {
        let plain = self.plain.lock().unwrap();
        let total = plain.pack_files.len();
        let total_size = plain.pack_total_size;
        drop(plain);

        match (self.tty, self.pack_bar.lock().unwrap().take()) {
            (true, Some(bar)) => bar.finish_with_message(pack_message(
                total,
                total,
                total_size,
                final_size,
                &[],
                true,
            )),
            _ => eprintln!("{}", self.pack_done_line(total, total_size, final_size)),
        }
    }
}

// -------- 工具 --------

/// 绘制进度条
fn progress_bar(fraction: f64) -> String {
    let filled = (fraction.clamp(0.0, 1.0) * BAR_WIDTH as f64).round() as usize;
    let empty = BAR_WIDTH - filled;
    format!("[{}{}]", "█".repeat(filled), "░".repeat(empty))
}

/// 人类可读的文件体积
fn format_size(bytes: u64) -> String {
    const UNITS: [&str; 5] = ["B", "KB", "MB", "GB", "TB"];
    let mut value = bytes as f64;
    let mut unit = 0;
    while value >= 1024.0 && unit < UNITS.len() - 1 {
        value /= 1024.0;
        unit += 1;
    }
    if unit == 0 {
        format!("{bytes} B")
    } else {
        format!("{value:.1} {}", UNITS[unit])
    }
}

/// 人类可读的耗时
fn format_duration(duration: Duration) -> String {
    if duration.as_secs() > 0 {
        format!(
            "{}.{:02}s",
            duration.as_secs(),
            duration.subsec_millis() / 10
        )
    } else {
        format!("{}ms", duration.as_millis())
    }
}

/// 获取路径的文件名 (兜底为完整路径)
fn file_name(path: &Path) -> String {
    path.file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_else(|| path.to_string_lossy().into_owned())
}

/// 格式化错误为 `路径[:行号]: 详情` 或纯详情
fn format_error(error: &Error) -> String {
    match &error.path {
        Some(path) => {
            let mut text = path.display().to_string();
            if let Some(line) = error.line {
                text.push_str(&format!(":{line}"));
            }
            format!("{text}: {}", error.detail)
        }
        None => error.detail.to_string(),
    }
}

/// 打包体积与压缩率描述
fn pack_sizes(size: u64, compressed: u64) -> String {
    let ratio = if size == 0 {
        0.0
    } else {
        compressed as f64 / size as f64 * 100.0
    };
    format!(
        "{} → {} (压缩 {ratio:.1}%)",
        format_size(size),
        format_size(compressed)
    )
}

/// 打包进度描述 (体积, 压缩率与待处理队列)
fn pack_message(
    processed: usize,
    total: usize,
    size: u64,
    compressed: u64,
    files: &[String],
    done: bool,
) -> String {
    let mut message = pack_sizes(size, compressed);
    if !done {
        let queue = files
            .iter()
            .skip(processed.min(total))
            .take(QUEUE_LEN)
            .cloned()
            .collect::<Vec<_>>()
            .join(" ");
        if !queue.is_empty() {
            message.push_str(&format!("  ← {queue}"));
        }
    }
    message
}

// -------- 主流程 --------

fn main() {
    // 解析参数 (clap 自动处理帮助, 版本与参数错误)
    let cli = Cli::parse();

    // 校验输出目录
    let output_dir = match std::path::absolute(&cli.output_dir) {
        Ok(dir) => dir,
        Err(error) => {
            eprintln!(
                "{}",
                style(format!(
                    "error: 无法解析输出目录 `{}`: {error}",
                    cli.output_dir.display()
                ))
                .for_stderr()
                .red()
            );
            process::exit(2);
        }
    };
    if !output_dir.is_dir() {
        eprintln!(
            "{}",
            style(format!("error: 输出目录不存在: {}", output_dir.display()))
                .for_stderr()
                .red()
        );
        process::exit(2);
    }

    let tty = io::stderr().is_terminal();
    let started = Instant::now();

    // 汇总
    let mut total_count = 0usize;
    let mut total_size = 0u64;
    let mut total_compressed = 0u64;
    let mut failed = 0usize;
    let mut destinations = HashSet::new();

    // 逐项目打包
    for project in &cli.projects {
        // 校验项目目录
        if !project.is_dir() {
            eprintln!(
                "{}",
                style(format!("error: 项目目录不存在: {}", project.display()))
                    .for_stderr()
                    .red()
            );
            failed += 1;
            continue;
        }
        let Some(name) = project.file_name() else {
            eprintln!(
                "{}",
                style(format!("error: 无法识别项目名称: {}", project.display()))
                    .for_stderr()
                    .red()
            );
            failed += 1;
            continue;
        };

        // 输出位置
        let name = name.to_string_lossy();
        let destination = output_dir.join(format!("{name}-snapshot.zip"));
        if !destinations.insert(destination.clone()) {
            eprintln!(
                "{}",
                style(format!(
                    "warning: 多个项目输出同名文件, 后者将覆盖前者: {}",
                    destination.display()
                ))
                .for_stderr()
                .yellow()
            );
        }

        // 打包
        let mut builder = PackerBuilder::default()
            .source(project)
            .destination(&destination)
            .compression(cli.compression.into())
            .with_progress(Reporter::new(name.to_string(), tty));
        if cli.follow_symlinks {
            builder = builder.follow_symlinks();
        }
        let result = builder.run();

        // 汇总
        total_count += result.count;
        total_size += result.total_size;
        total_compressed += result.final_size;
        if result.aborted {
            eprintln!(
                "{}",
                style("error: 打包被终止, 压缩包未完整生成")
                    .for_stderr()
                    .red()
            );
            failed += 1;
        } else if !result.errors.is_empty() {
            eprintln!(
                "{}",
                style(format!("error: 共 {} 个错误", result.errors.len()))
                    .for_stderr()
                    .red()
            );
            failed += 1;
        }
    }

    // 总体汇总
    if failed == 0 {
        eprintln!(
            "{}",
            style(format!(
                "完成 {} 个项目, 共 {} 个文件 · {} → {} (耗时 {})",
                cli.projects.len(),
                total_count,
                format_size(total_size),
                format_size(total_compressed),
                format_duration(started.elapsed())
            ))
            .for_stderr()
            .green()
        );
    } else {
        eprintln!(
            "{}",
            style(format!(
                "完成 {}/{} 个项目, {} 个失败",
                cli.projects.len() - failed,
                cli.projects.len(),
                failed
            ))
            .for_stderr()
            .red()
        );
    }
    process::exit(if failed == 0 { 0 } else { 1 });
}

#[cfg(test)]
mod tests {
    use webgal_snapshot::ErrorKind;

    use super::*;

    #[test]
    fn compression_mapping() {
        assert!(matches!(
            CompressionArg::Stored.into(),
            CompressionMethod::Stored
        ));
        assert!(matches!(
            CompressionArg::Deflated.into(),
            CompressionMethod::Deflated
        ));
        assert!(matches!(
            CompressionArg::Deflate64.into(),
            CompressionMethod::Deflate64
        ));
        assert!(matches!(
            CompressionArg::Bzip2.into(),
            CompressionMethod::Bzip2
        ));
        assert!(matches!(
            CompressionArg::Zstd.into(),
            CompressionMethod::Zstd
        ));
        assert!(matches!(
            CompressionArg::Lzma.into(),
            CompressionMethod::Lzma
        ));
        assert!(matches!(
            CompressionArg::Ppmd.into(),
            CompressionMethod::Ppmd
        ));
        assert_eq!(CompressionArg::Deflated.to_string(), "deflated");
    }

    #[test]
    fn format_size_units() {
        assert_eq!(format_size(0), "0 B");
        assert_eq!(format_size(1023), "1023 B");
        assert_eq!(format_size(1024), "1.0 KB");
        assert_eq!(format_size(1536), "1.5 KB");
        assert_eq!(format_size(5 * 1024 * 1024), "5.0 MB");
    }

    #[test]
    fn progress_bar_width_and_clamp() {
        assert_eq!(progress_bar(0.0), "[░░░░░░░░░░░░░░░░░░░░]");
        assert_eq!(progress_bar(1.0), "[████████████████████]");
        assert_eq!(progress_bar(0.5).chars().count(), 22);
        assert_eq!(progress_bar(-1.0), progress_bar(0.0));
        assert_eq!(progress_bar(2.0), progress_bar(1.0));
    }

    #[test]
    fn format_error_shapes() {
        let error = Error::without_path(ErrorKind::MissingSource);
        assert_eq!(format_error(&error), "缺失打包目录");

        let error = Error::with_line(
            PathBuf::from("game/scene/start.txt"),
            3,
            ErrorKind::MissingResource,
        );
        assert_eq!(
            format_error(&error),
            "game/scene/start.txt:3: 引用的资源不存在"
        );
    }

    #[test]
    fn file_name_fallback() {
        assert_eq!(file_name(Path::new("a/b/c.png")), "c.png");
        assert_eq!(file_name(Path::new("plain")), "plain");
    }

    #[test]
    fn pack_message_renders_sizes_and_queue() {
        let files = vec!["a".into(), "b".into(), "c".into(), "d".into()];
        // 打包中: 体积, 压缩率与待处理队列
        let message = pack_message(1, 4, 1024, 512, &files, false);
        assert_eq!(message, "1.0 KB → 512 B (压缩 50.0%)  ← b c d");
        // 打包完成: 不再显示待处理队列
        let message = pack_message(4, 4, 1024, 512, &files, true);
        assert_eq!(message, "1.0 KB → 512 B (压缩 50.0%)");
        // 空体积不除零
        assert_eq!(
            pack_message(0, 4, 0, 0, &files, false),
            "0 B → 0 B (压缩 0.0%)  ← a b c"
        );
    }

    #[test]
    fn templates_parse() {
        // 模板仅在终端模式使用, 这里确保语法有效
        ProgressStyle::with_template(SCAN_TEMPLATE).unwrap();
        ProgressStyle::with_template(PACK_TEMPLATE).unwrap();
    }

    #[test]
    fn done_lines_render() {
        let reporter = Reporter::new("demo".to_string(), false);
        assert_eq!(
            reporter.scan_done_line(14, 340),
            "扫描 demo  完成 14 个文件 · 340 B"
        );
        assert_eq!(
            reporter.pack_done_line(14, 340, 2048),
            format!(
                "打包 demo  {} 14/14 (100%)  340 B → 2.0 KB (压缩 602.4%)",
                progress_bar(1.0)
            )
        );
    }
}
